export circuit verifyMembership(
  leaf: Field,
  proofPath: [Field; depth],
  root: Field
): [] {
  // Tamaño de la prueba: O(___ n)
  let computed = leaf;
  for (i in 0..depth) {
    computed = hash(computed, proofPath[i]);
  }
  assert(computed == root);
}

export circuit verifyEligibility(
  leaf: witness<Field>,
  merkleProof: [Field; depth],
  root: Field,
  voteCommitment: Commitment
): [] {
  assert(verifyMerkle(leaf, merkleProof, root));
  // El circuito verifica el ___ junto con la prueba Merkle.
}
